/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { StringManager } from "../../src/i18n/StringManager.js";
import MotionsOfTheSunColors from "../../src/MotionsOfTheSunColors.js";
import { MotionsOfTheSunPreferencesModel } from "../../src/preferences/MotionsOfTheSunPreferencesModel.js";
import { SiderealSolarTimeScreen } from "../../src/sidereal-solar-time/SiderealSolarTimeScreen.js";
import { SunPathsScreen } from "../../src/sun-paths/SunPathsScreen.js";
import { ZodiacScreen } from "../../src/zodiac/ZodiacScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();
  const screenNames = stringManager.getScreenNames();

  // Simulation-specific preferences; initial values come from motionsOfTheSunQueryParameters.
  const simPreferences = new MotionsOfTheSunPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new SunPathsScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.sunPathsStringProperty,
      tandem: Tandem.ROOT.createTandem("sunPathsScreen"),
      backgroundColorProperty: MotionsOfTheSunColors.backgroundColorProperty,
      defaultLatitudeProperty: simPreferences.defaultLatitudeProperty,
    }),
    new SiderealSolarTimeScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.siderealSolarTimeStringProperty,
      tandem: Tandem.ROOT.createTandem("siderealSolarTimeScreen"),
      backgroundColorProperty: MotionsOfTheSunColors.backgroundColorProperty,
    }),
    new ZodiacScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.zodiacStringProperty,
      tandem: Tandem.ROOT.createTandem("zodiacScreen"),
      backgroundColorProperty: MotionsOfTheSunColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { MotionsOfTheSunColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
